INSERT INTO "_issue_titles" VALUES
  ('category-advertisement', 'Advertisement and banner issues', 'ಜಾಹೀರಾತು ಮತ್ತು ಬ್ಯಾನರ್ ಸಮಸ್ಯೆಗಳು'),
  ('category-e-khata-khata-services', 'Khata and e-khata services', 'ಖಾತಾ ಮತ್ತು ಇ-ಖಾತಾ ಸೇವೆಗಳು'),
  ('category-electrical', 'Electrical and street lighting issues', 'ವಿದ್ಯುತ್ ಮತ್ತು ಬೀದಿ ದೀಪ ಸಮಸ್ಯೆಗಳು'),
  ('category-forest', 'Trees and wildlife issues', 'ಮರ ಮತ್ತು ವನ್ಯಜೀವಿ ಸಮಸ್ಯೆಗಳು'),
  ('category-health-dept', 'Public health issues', 'ಸಾರ್ವಜನಿಕ ಆರೋಗ್ಯ ಸಮಸ್ಯೆಗಳು'),
  ('category-indira-canteen', 'Indira Canteen issues', 'ಇಂದಿರಾ ಕ್ಯಾಂಟೀನ್ ಸಮಸ್ಯೆಗಳು'),
  ('category-lakes', 'Lake issues', 'ಕೆರೆ ಸಮಸ್ಯೆಗಳು'),
  ('category-markets', 'Market issues', 'ಮಾರುಕಟ್ಟೆ ಸಮಸ್ಯೆಗಳು'),
  ('category-other-electrical', 'Other electrical and street lighting issues', 'ಇತರ ವಿದ್ಯುತ್ ಮತ್ತು ಬೀದಿ ದೀಪ ಸಮಸ್ಯೆಗಳು'),
  ('category-other-forest', 'Other trees and wildlife issues', 'ಇತರ ಮರ ಮತ್ತು ವನ್ಯಜೀವಿ ಸಮಸ್ಯೆಗಳು'),
  ('category-other-health-dept', 'Other public health issues', 'ಇತರ ಸಾರ್ವಜನಿಕ ಆರೋಗ್ಯ ಸಮಸ್ಯೆಗಳು'),
  ('category-other-road-maintenance-engg', 'Other road maintenance issues', 'ಇತರ ರಸ್ತೆ ನಿರ್ವಹಣೆ ಸಮಸ್ಯೆಗಳು'),
  ('category-other-solid-waste-garbage-related', 'Other solid waste and garbage issues', 'ಇತರ ಘನ ತ್ಯಾಜ್ಯ ಮತ್ತು ಕಸದ ಸಮಸ್ಯೆಗಳು'),
  ('category-parks-and-play-grounds', 'Parks and playground issues', 'ಉದ್ಯಾನ ಮತ್ತು ಆಟದ ಮೈದಾನ ಸಮಸ್ಯೆಗಳು'),
  ('category-revenue-department', 'Revenue department issues', 'ಕಂದಾಯ ಇಲಾಖೆ ಸಮಸ್ಯೆಗಳು'),
  ('category-road-infrastructure', 'Road infrastructure issues', 'ರಸ್ತೆ ಮೂಲಸೌಕರ್ಯ ಸಮಸ್ಯೆಗಳು'),
  ('category-road-maintenance-engg', 'Road maintenance issues', 'ರಸ್ತೆ ನಿರ್ವಹಣೆ ಸಮಸ್ಯೆಗಳು'),
  ('category-sanitation', 'Sanitation issues', 'ನೈರ್ಮಲ್ಯ ಸಮಸ್ಯೆಗಳು'),
  ('category-storm-water-drain-swd', 'Storm water drain issues', 'ಮಳೆನೀರು ಚರಂಡಿ ಸಮಸ್ಯೆಗಳು'),
  ('category-town-planning', 'Town planning issues', 'ನಗರ ಯೋಜನೆ ಸಮಸ್ಯೆಗಳು'),
  ('category-veterinary', 'Stray animal and veterinary issues', 'ಬೀದಿ ಪ್ರಾಣಿ ಮತ್ತು ಪಶುವೈದ್ಯಕೀಯ ಸಮಸ್ಯೆಗಳು'),
  ('debris-removal-construction-material', 'Debris or construction material on road', 'ರಸ್ತೆಯ ಮೇಲೆ ಅವಶೇಷ ಅಥವಾ ನಿರ್ಮಾಣ ಸಾಮಗ್ರಿ'),
  ('dengue-positive', 'Dengue related health issues', 'ಡೆಂಗ್ಯೂ ಸಂಬಂಧಿತ ಆರೋಗ್ಯ ಸಮಸ್ಯೆಗಳು'),
