  ('garbage-dump', 'Garbage black spots', 'ಕಸದ ಬ್ಲಾಕ್ ಸ್ಪಾಟ್‌ಗಳು'),
  ('garbage-vehicle-not-arrived', 'Garbage pickup vehicle absent', 'ಕಸ ಸಂಗ್ರಹ ವಾಹನ ಬರುತ್ತಿಲ್ಲ'),
