  ('removal-of-dead-fallen-trees', 'Fallen trees causing obstructions', 'ಅಡ್ಡಿಯಾಗುವ ಬಿದ್ದ ಮರಗಳು'),
  ('road-cutting', 'Road cutting and digging', 'ರಸ್ತೆ ಕಡಿತ ಮತ್ತು ಅಗೆಯುವಿಕೆ'),
  ('road-infrastructure', 'Road maintenance and upkeep', 'ರಸ್ತೆ ನಿರ್ವಹಣೆ ಮತ್ತು ಕಾಪಾಡುವಿಕೆ'),
  ('road-side-drains', 'Roadside drain problems', 'ರಸ್ತೆ ಬದಿಯ ಚರಂಡಿ ಸಮಸ್ಯೆಗಳು'),
  ('spraying', 'Pest control spraying', 'ಕೀಟ ನಿಯಂತ್ರಣ ಸಿಂಪಡಣೆ'),
  ('street-light-not-working', 'Street lights not functional', 'ಬೀದಿ ದೀಪಗಳು ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತಿಲ್ಲ'),
